// ═══════════════════════════════════════════════════════════════
//  Approval Dashboard
//  GET  branch → the queue, with form buttons (no JS)
//  POST branch → a full confirmation page
//
//  multipleMethods routes by output index, not by $json.method.
//  GetPendingActions and GetIncidents need "Always Output Data".
// ═══════════════════════════════════════════════════════════════

// Safe node reader. Returns [] if the node did not run on this branch.
function tryNode(name) {
  try {
    const items = $(name).all();
    return Array.isArray(items) ? items : [];
  } catch (e) {
    return [];
  }
}

function firstJson(name) {
  const items = tryNode(name);
  return items.length ? (items[0].json || {}) : {};
}

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function slug(s) {
  return String(s ?? 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '-');
}

function fmt(date) {
  if (!date) return '—';
  const d = new Date(date);
  if (isNaN(d)) return String(date);
  const p = n => String(n).padStart(2, '0');
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

const CSS = `
  :root{
    --bg:#0e0918; --card:#171023; --edge:rgba(255,255,255,.08);
    --txt:#fff; --mute:rgba(255,255,255,.55); --dim:rgba(255,255,255,.35);
    --orange:#fd8925; --green:#35a670; --red:#d91616; --pink:#eb4b72; --blue:#077ac7;
  }
  *{box-sizing:border-box}
  body{
    margin:0; background:var(--bg); color:var(--txt);
    font-family:'Lexend',ui-sans-serif,system-ui,sans-serif;
    letter-spacing:-.02em; padding:48px 24px 80px;
  }
  .wrap{max-width:1280px;margin:0 auto}
  .narrow{max-width:760px}
  h1{font-size:28px;font-weight:600;margin:0 0 6px}
  .lede{color:var(--mute);font-size:15px;margin:0 0 32px;max-width:660px;line-height:1.6}
  .card{background:var(--card);border:1px solid var(--edge);border-radius:14px;padding:24px;position:relative;overflow:hidden}
  .card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--pink),var(--orange))}
  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin-bottom:28px}
  .k{font-size:13px;color:var(--mute);margin-bottom:8px}
  .v{font-size:34px;font-weight:600;line-height:1}
  .tablecard{background:var(--card);border:1px solid var(--edge);border-radius:14px;overflow:hidden}
  .scroll{overflow-x:auto}
  table{width:100%;border-collapse:collapse}
  th{
    text-align:left;font-size:12px;font-weight:600;text-transform:uppercase;
    letter-spacing:.08em;color:var(--mute);padding:16px 20px;
    border-bottom:1px solid var(--edge);white-space:nowrap;
  }
  td{padding:18px 20px;border-bottom:1px solid rgba(255,255,255,.04);font-size:14px;vertical-align:top}
  tr:last-child td{border-bottom:0}
  tbody tr:hover{background:rgba(255,255,255,.02)}
  .mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:14px;margin-bottom:4px}
  .sub{color:var(--mute);font-size:13px;line-height:1.5}
  .dim{color:var(--dim)}
  .arrow{color:var(--mute);margin:0 10px}
  .just{max-width:400px;line-height:1.55;color:rgba(255,255,255,.85);font-size:13px}
  .nowrap{white-space:nowrap}
  .badge{display:inline-block;padding:4px 12px;border-radius:20px;font-size:12px;font-weight:600;text-transform:capitalize}
  .sev-critical{background:rgba(217,22,22,.18);color:#ff6b6b}
  .sev-high{background:rgba(253,137,37,.15);color:var(--orange)}
  .sev-medium{background:rgba(7,122,199,.15);color:#4da3dd}
  .sev-low{background:rgba(255,255,255,.08);color:var(--mute)}
  .sev-unknown{background:rgba(255,255,255,.06);color:var(--dim)}
  .st-open{background:rgba(253,137,37,.15);color:var(--orange)}
  .st-investigating{background:rgba(7,122,199,.15);color:#4da3dd}
  .st-resolved{background:rgba(53,166,112,.15);color:var(--green)}
  .st-unknown{background:rgba(255,255,255,.06);color:var(--dim)}
  form{margin:0;display:flex;gap:8px}
  .btn{
    font-family:inherit;font-size:13px;font-weight:600;letter-spacing:-.01em;
    border:0;border-radius:8px;padding:9px 16px;cursor:pointer;
  }
  .approve{background:var(--green);color:#06210f}
  .reject{background:transparent;color:var(--mute);box-shadow:inset 0 0 0 1px var(--edge)}
  .empty{text-align:center;padding:72px 24px}
  .empty-title{font-size:16px;font-weight:600;color:var(--mute);margin-bottom:8px}
  .empty-sub{font-size:14px;color:var(--dim);max-width:420px;margin:0 auto;line-height:1.6}
  .foot{margin-top:24px;color:var(--mute);font-size:13px;line-height:1.6;max-width:660px}
  .verdict{font-size:72px;font-weight:700;line-height:1;margin:0 0 12px;letter-spacing:-.04em}
  .verdict.ok{color:var(--green)}
  .verdict.no{color:var(--mute)}
  .verdict-sub{font-size:17px;color:var(--mute);margin:0 0 40px;line-height:1.6;max-width:600px}
  .detail{margin-bottom:28px}
  .detail .row{display:flex;padding:16px 0;border-bottom:1px solid rgba(255,255,255,.06);gap:24px}
  .detail .row:last-child{border-bottom:0}
  .detail .lab{flex:0 0 190px;color:var(--mute);font-size:13px;padding-top:2px}
  .detail .val{flex:1;font-size:15px;line-height:1.6}
  .quote{color:rgba(255,255,255,.85);font-size:14px;line-height:1.65;border-left:2px solid var(--edge);padding-left:18px}
  .link{
    display:inline-block;margin-top:8px;font-size:14px;font-weight:600;
    color:var(--txt);text-decoration:none;background:var(--card);
    border:1px solid var(--edge);border-radius:8px;padding:12px 22px;
  }
  .stamp{font-size:13px;color:var(--dim);margin-top:32px;line-height:1.6}
`;

function page(title, bodyHtml, extraClass) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${esc(title)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>${CSS}</style>
</head>
<body>
<div class="wrap ${extraClass || ''}">
${bodyHtml}
</div>
</body>
</html>`;
}

// ═══════════════════════════════════════════════════════════════
//  POST branch — confirmation page
// ═══════════════════════════════════════════════════════════════
const postPayload = firstJson('SetData');

if (postPayload.decision) {
  const req = firstJson('GetPendingAction');

  let backUrl = '?';
  const wh = firstJson('Webhook');
  if (wh.webhookUrl) backUrl = wh.webhookUrl;

  const approved = String(postPayload.decision).toLowerCase() === 'approve';
  const verdict = approved ? 'Approved' : 'Rejected';
  const verdictSub = approved
    ? 'You applied this change. The incidents table has been updated.'
    : 'Nothing was changed. The incident is exactly as it was.';

  const changeCell = approved
    ? `<span class="badge st-${esc(slug(req.new_value))}">${esc(req.new_value || 'unknown')}</span>
       <span class="sub dim" style="margin-left:12px">applied</span>`
    : `<span class="badge st-unknown">${esc(req.new_value || 'unknown')}</span>
       <span class="sub dim" style="margin-left:12px">declined</span>`;

  const confirmBody = `
  <div class="verdict ${approved ? 'ok' : 'no'}">${verdict}</div>
  <p class="verdict-sub">${verdictSub}</p>

  <div class="card detail">
    <div class="row">
      <div class="lab">Incident</div>
      <div class="val"><span class="mono">${esc(req.incident_id || '—')}</span></div>
    </div>
    <div class="row">
      <div class="lab">Requested change</div>
      <div class="val">${changeCell}</div>
    </div>
    <div class="row">
      <div class="lab">Requested by</div>
      <div class="val">${esc(req.requested_by || 'agent')}<span class="sub dim" style="margin-left:12px">${esc(fmt(req.created_at || req.createdAt))}</span></div>
    </div>
    <div class="row">
      <div class="lab">Its justification</div>
      <div class="val"><div class="quote">${esc(req.justification || 'No justification given.')}</div></div>
    </div>
  </div>

  <a class="link" href="${esc(backUrl)}">Back to the queue</a>

  <p class="stamp">
    The agent asked for this change and stopped. A person decided it.
    There is no tool in the agent's catalogue that writes to the incidents table.
  </p>`;

  return [{ json: { html: page(verdict, confirmBody, 'narrow') } }];
}

// ═══════════════════════════════════════════════════════════════
//  GET branch — the queue
// ═══════════════════════════════════════════════════════════════
const pending = tryNode('GetPendingActions')
  .map(i => i.json)
  .filter(r => r && r.id != null && r.incident_id);

const incidentIndex = {};
tryNode('GetIncidents').forEach(i => {
  const r = i.json;
  if (r && r.incident_id) incidentIndex[r.incident_id] = r;
});

const rows = pending.map(r => {
  const inc = incidentIndex[r.incident_id] || {};
  return {
    rowId: r.id,
    incidentId: r.incident_id,
    incidentTitle: inc.title || 'Incident not found',
    severity: slug(inc.severity),
    currentStatus: inc.status || 'unknown',
    proposed: r.new_value || 'unknown',
    actionType: r.action_type || '—',
    assignedTo: inc.assigned_to || '—',
    justification: r.justification || 'No justification given.',
    requestedBy: r.requested_by || 'agent',
    created: r.created_at || r.createdAt
  };
});

const affected = new Set(rows.map(r => r.incidentId)).size;

const tableBody = rows.length
  ? rows.map(r => `
      <tr>
        <td>
          <div class="mono">${esc(r.incidentId)}</div>
          <div class="sub">${esc(r.incidentTitle)}</div>
          <div class="sub dim">${esc(r.assignedTo)}</div>
        </td>
        <td><span class="badge sev-${esc(r.severity)}">${esc(r.severity)}</span></td>
        <td class="nowrap">
          <span class="badge st-${esc(slug(r.currentStatus))}">${esc(r.currentStatus)}</span>
          <span class="arrow">&rarr;</span>
          <span class="badge st-${esc(slug(r.proposed))}">${esc(r.proposed)}</span>
          <div class="sub dim" style="margin-top:8px">${esc(r.actionType)}</div>
        </td>
        <td class="just">${esc(r.justification)}</td>
        <td class="sub nowrap">
          ${esc(fmt(r.created))}
          <div class="dim" style="margin-top:4px">by ${esc(r.requestedBy)}</div>
        </td>
        <td>
          <form method="POST">
            <input type="hidden" name="id" value="${esc(r.rowId)}">
            <button class="btn approve" type="submit" name="decision" value="approve">Approve</button>
            <button class="btn reject"  type="submit" name="decision" value="reject">Reject</button>
          </form>
        </td>
      </tr>`).join('')
  : `<tr><td colspan="6" class="empty">
       <div class="empty-title">Nothing waiting on you</div>
       <div class="empty-sub">When the agent requests a change to an incident it will appear here for review.</div>
     </td></tr>`;

const queueBody = `
  <h1>Approval Dashboard</h1>
  <p class="lede">
    The agent can request a change to an incident. It cannot make one. Every row below is waiting on a person, and this page is the only thing in the system that writes to the incidents table.
  </p>

  <div class="stats">
    <div class="card"><div class="k">Waiting on you</div><div class="v">${rows.length}</div></div>
    <div class="card"><div class="k">Incidents affected</div><div class="v">${affected}</div></div>
    <div class="card"><div class="k">Agent write access</div><div class="v">None</div></div>
  </div>

  <div class="tablecard">
    <div class="scroll">
      <table>
        <thead>
          <tr>
            <th>Incident</th>
            <th>Severity</th>
            <th>Proposed change</th>
            <th>The agent's justification</th>
            <th>Requested</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${tableBody}</tbody>
      </table>
    </div>
  </div>

  <p class="foot">
    Approving writes the new status to the incidents table and marks the request approved. Rejecting leaves the incident untouched.
  </p>`;

return [{ json: { html: page('Approval Dashboard', queueBody) } }];
